/* aspect-ratio：固定宽高比 */

/* 16:9 宽屏比例 */
.ratio-16-9 {
  aspect-ratio: 16 / 9;
  width: 100%;
  /* 高度自动计算，保持 16:9 */
}

/* 1:1 正方形 */
.ratio-square {
  aspect-ratio: 1 / 1;
}

/* 4:3 传统比例 */
.ratio-4-3 {
  aspect-ratio: 4 / 3;
}

/* 21:9 超宽屏 */
.ratio-ultrawide {
  aspect-ratio: 21 / 9;
}

/* 与 min-width/max-width 配合 */
.responsive-ratio {
  aspect-ratio: 16 / 9;
  width: 100%;
  max-width: 800px;
}

