/* object-fit：替换元素的填充方式 */

/* cover：裁剪填满（保持比例） */
.img-cover {
  width: 100%;
  height: 100%;
  object-fit: cover;
  /* 图片填满容器，超出部分裁剪 */
}

/* contain：完整显示（可能留白） */
.img-contain {
  width: 100%;
  height: 100%;
  object-fit: contain;
  /* 图片完整显示，可能有留白 */
}

/* fill：拉伸填满（变形） */
.img-fill {
  width: 100%;
  height: 100%;
  object-fit: fill;
  /* 拉伸填满，可能变形（默认值） */
}

/* none：保持原始尺寸 */
.img-none {
  width: 100%;
  height: 100%;
  object-fit: none;
  /* 不缩放，保持原始尺寸 */
}

/* scale-down：取 none 或 contain 中较小的 */
.img-scale-down {
  object-fit: scale-down;
}

/* object-position：调整显示位置 */
.img-position {
  object-fit: cover;
  object-position: center top;
  /* 居中顶部 */
}

/* 防止 CLS（布局偏移）最佳实践 */
.img-cls {
  width: 100%;
  aspect-ratio: 16 / 9;
  object-fit: cover;
  /* 图片加载前就预留好空间 */
}
